```python
import bpy

def invert_vertex_group(obj, group_name):
    """Invert the weights of a vertex group."""
    if group_name not in obj.vertex_groups:
        raise ValueError(f"Vertex group '{group_name}' not found in object '{obj.name}'")

    vertex_group = obj.vertex_groups[group_name]
    for vertex in obj.data.vertices:
        try:
